n_ep = len(DG['wwb_dec96_jun97'])
d = {
 "methods_note": "Daily TAO/TRITON winds and 20 °C isotherm depth on the equator give an independent, directly observed check on the reanalysis bursts and trace the Kelvin waves; the definitions (westerly ≥ 5 m s⁻¹ on ≥ 2 days at 147°E–180°; intraseasonal isotherm peaks ≥ 8 m) were fixed before the results were examined " + c('taodata', 'r1diag') + ".",
 "wwb_sentence": f"On Paper 1's definitions the reanalysis contains {n_ep} bursts between December 1996 and June 1997 and {DG['wwb_count_1997']} in calendar 1997 — the most of any year in 1979–2001 (mean {DG['wwb_mean_1979_2001']} a year; 1982 had {DG['wwb_count_1982']}, while 1995 and 1996 had {DG['wwb_count_1995']} and {DG['wwb_count_1996']}). The strongest were on 20–31 December 1996 (+{W['1996-12-20']['peak_anom_ms']} m s⁻¹ at {W['1996-12-20']['peak_lon_E']:g}°E), 3–19 March 1997 (+{W['1997-03-03']['peak_anom_ms']} m s⁻¹ at {W['1997-03-03']['peak_lon_E']:g}°E) and 10–21 April 1997 (+{W['1997-04-10']['peak_anom_ms']} m s⁻¹ at {W['1997-04-10']['peak_lon_E']:g}°E). TAO moorings observed the same episodes directly, with daily westerlies of up to 8.7 m s⁻¹ at 156°E in late December, 9.9 m s⁻¹ at 147°E in late February – early March and 11.0 m s⁻¹ at 165°E in mid-April " + c('r1diag', 'taodata') + ".",
 "kelvin_sentence": f"The TAO thermocline record traces two of the resulting downwelling Kelvin waves: an intraseasonal deepening at 165°E on {KW[0]['start_165E'][8:]} January reached 110°W on {KW[0]['arrive_110W'][8:]} February (about {KW[0]['speed_ms']} m s⁻¹), and one at 165°E on {KW[1]['start_165E'][8:]} March reached 110°W on {KW[1]['arrive_110W'][8:]} April (about {KW[1]['speed_ms']} m s⁻¹) " + c('taodata') + ".",
 "mjo_paragraph": f"The MJO was unusually active through the onset: the PSL OLR MJO index stayed at or above 1 almost continuously from late October 1996 to mid-June 1997, intraseasonal OLR variance over the Indian Ocean and western Pacific in October 1996 – March 1997 was the largest of 22 seasons in 1979–2001, and the bursts of 25 December, 13 March and 28 March occurred at index amplitudes of 2.7–3.3 " + c('r1diag') + f". Indices disagree for some bursts: on 13 April the OLR-based index was {W['1997-04-10']['omi_amp_at_peak']:.1f} but a circulation-weighted index only {W['1997-04-10']['wh_like_amp_at_peak']}, as expected when indices weight convection and winds differently " + c('kiladis2014') + ". In a wave model forced with observed winds, MJO-forced downwelling Kelvin waves reached 15–20 cm in sea level, an order of magnitude larger than the waves reflected from the western boundary " + c('mcphadenyu1999') + ". Yet an active MJO in January–April 1996 produced no El Niño, and the late-1996 bursts intensified to over 9 m s⁻¹ in the Pacific while the MJO's own westerlies had fallen below 2 m s⁻¹ over the Maritime Continent " + c('yurienecker1998') + ".",
 "volcano_sentence": "The Smithsonian Global Volcanism Program catalogue lists no eruption of VEI ≥ 4 anywhere in 1995–97; the most recent tropical VEI 4 eruption was Rabaul (Papua New Guinea, 4°S) in September 1994, more than two years before the December 1996 burst " + c('gvp') + ". Volcanic forcing is therefore not a candidate for this event.",
}
