post = [
 {"id": "bursts", "title": "Westerly wind events and Kelvin waves, December 1996 – June 1997", "html": "<p>Reanalysis bursts on Paper 1's definitions (1000 hPa anomaly ≥ 5 m s⁻¹, ≥ 3 days, ≥ 10° of longitude, 5°S–5°N, 120°E–150°W), with the PSL OLR MJO index (OMI) and the circulation-weighted index at the burst peak " + c('r1diag') + ".</p>",
  "table": {"cols": ["Start", "End", "Peak", "Peak anomaly (m s⁻¹)", "Peak lon", "Extent", "OMI", "Circulation index"], "cls": "data",
            "rows": [[w['start'], w['end'], w['peak'], f"{w['peak_anom_ms']}", f"{w['peak_lon_E']:g}°E" if w['peak_lon_E'] <= 180 else f"{360 - w['peak_lon_E']:g}°W",
                      f"{w['lon_w']:g}°E–" + (f"{w['lon_e']:g}°E" if w['lon_e'] <= 180 else f"{360 - w['lon_e']:g}°W"), f"{w['omi_amp_at_peak']:.2f}", f"{w['wh_like_amp_at_peak']}"] for w in DG['wwb_dec96_jun97']],
            "note": "Directly observed TAO episodes (daily westerly ≥ 5 m s⁻¹ on ≥ 2 days at 147°E, 156°E, 165°E or 180°): " + "; ".join(f"{fd(e['start'])} – {fd(e['end'])} ({e['max_u_ms']} m s⁻¹ at {e['max_lon_E']:g}°E)" for e in DG['tao_westerly_episodes']) + ". TAO wind records are incomplete at 147°E (37% of days) and 156°E (64%)."}},
 {"id": "mjo", "title": "MJO contribution (assessment)", "html": "<p><b>Answer.</b> Strong evidence that the MJO set the timing and much of the amplitude of the onset bursts, through Kelvin waves an order of magnitude larger than boundary reflections " + c('mcphadenyu1999', 'bergman2001') + "; but the MJO was not sufficient on its own — an active MJO in early 1996 produced no El Niño, and the bursts that mattered were intensified locally by cold surges and twin circulations " + c('yurienecker1998') + ". Bergman et al. conclude that the MJO is relevant to the timing and initial growth of El Niño rather than responsible for the event itself " + c('bergman2001') + ". One intermediate coupled model initialised on 1 January 1997 becomes about 50% stronger when rectified MJO winds are included " + c('kesslerkleeman2000') + ". Statistically, MJO events warm the waveguide only when they contain a westerly wind event " + c('chiodi2014') + ".</p><p><b>Compared with 1982.</b> The 1996–97 season had " + f"{DG['mjo_days_1996_97']}" + " days with the circulation-weighted index at or above 1 against " + f"{DG['mjo_days_1981_82']}" + " in 1981–82, and the bursts in calendar 1997 outnumber those of 1982 (" + f"{DG['wwb_count_1997']} vs {DG['wwb_count_1982']}" + ") on identical definitions " + c('r1diag') + ". In the mature phase (Oct 1997 – Mar 1998) intraseasonal OLR variance over 60°E–150°E fell to " + f"{DG['olr_io_wp_var_1997_98']}" + " W² m⁻⁴ (22-season mean 233), consistent with the weak eastward MJO propagation reported for the mature stage " + c('li2023') + ".</p>"},
]
sections = [
 {"id": "scope", "title": "Evidence base: scope, index and data", "html": f"""<p><b>Primary index:</b> NOAA's Relative Oceanic Niño Index (RONI), official since 1 February 2026 {c('noaa2026', 'lheureux2024')}. On RONI the 1997–98 peak is +2.28 (NDJ 1997); on the traditional ONI it is +2.37. The two agree within 0.1 °C for this event, unlike 1982–83 (RONI +2.40, ONI +2.14).</p>
<p><b>Observing system in 1997.</b> The first strong El Niño observed from start to finish by the TOGA observing system — the TAO array of moored buoys, drifting buoys, island tide gauges, ship XBT lines — and by satellite winds, SST and TOPEX/Poseidon sea level (from 1992) {c('mcphaden1998tao', 'mcphaden1999', 'picaut2002', 'delcroix2000')}. Onset, growth and termination are therefore documented daily along the equator, which allows heat-budget and wave analyses that were impossible for 1982. Argo did not yet exist; the subsurface off the equator and outside the array remains less certain.</p>"""},
 {"id": "data", "title": "Monthly indices, Jul 1995 – Dec 1998", "html": "<p>Values from NOAA CPC, PMEL and NCEI files as held in the site's data archive; read from the source files, not retyped.</p>",
  "table": {"cols": ["Month", "Season", "RONI", "ONI", "rel. Niño 3.4 (OISST)", "Niño 3.4 (OISST)", "Niño 1+2 (OISST)", "SOI", "W Pac trades", "C Pac trades", "C Pac OLR", "Heat content 180–100°W", "WWV", "DMI (CPC)", "PDO"], "rows": rows, "cls": "data",
            "note": "RONI and ONI are three-month means centred on the month. SOI and trade-wind indices are standardized (negative = El Niño-like). OLR in W m⁻² (negative = more convection). Heat content in °C vs 1981–2010; WWV in 10¹⁴ m³; DMI in °C; PDO standardized."}},
]

